# Configuration
BASE_URL = "https://sis.cedar.edu.pk/uploads/"  # Replace with your actual base URL
FILE_TYPES = [".jpg", ".png", ".jpeg", ".gif", ".bmp"]  # List of possible file extensions

SAVE_DIR = "downloads"
INVALID_URLS_FILE = "invalid_urls.txt"

# Ensure save directory exists
os.makedirs(SAVE_DIR, exist_ok=True)

# List to store invalid IDs
invalid_ids = []

for img_id in IDS:
    valid = False
    for ext in FILE_TYPES:
        url = f"{BASE_URL}{img_id}{ext}"
        filename = os.path.join(SAVE_DIR, f"{img_id}{ext}")
        
        try:
            response = requests.get(url, stream=True)
            if response.status_code == 200:
                with open(filename, "wb") as file:
                    for chunk in response.iter_content(1024):
                        file.write(chunk)
                print(f"Downloaded: {filename}")
                valid = True
                break  # Stop checking other extensions if one is found
            else:
                print(f"Invalid URL: {url}")
        except requests.RequestException as e:
            print(f"Error downloading {url}: {e}")
    
    if not valid:
        invalid_ids.append(img_id)

# Save invalid IDs to file
if invalid_ids:
    with open(INVALID_URLS_FILE, "w") as file:
        file.write("\n".join(invalid_ids))
    print(f"Invalid IDs saved to {INVALID_URLS_FILE}")